import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        long n = nextLong();
        long a = 0, b = 1;
        while (b < n) {
            long c = a + b;
            a = b;
            b = c;
        }
        System.out.println(Math.min(n - a, b - n));
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

